def solve() -> None:
    # Read the 4x4 board
    board = [list(input().strip()) for _ in range(4)]

    # All possible directions to form three in a row
    directions = [
        (0, 1),   # horizontal
        (1, 0),   # vertical
        (1, 1),   # main diagonal
        (1, -1)   # anti-diagonal
    ]

    def check_win_after_move(r: int, c: int) -> bool:
        """Check if placing 'x' at (r,c) would create three in a row."""
        for dr, dc in directions:
            count = 1  # the cell we just placed
            # Check forward direction
            nr, nc = r + dr, c + dc
            while 0 <= nr < 4 and 0 <= nc < 4 and board[nr][nc] == 'x':
                count += 1
                nr += dr
                nc += dc
            # Check backward direction
            nr, nc = r - dr, c - dc
            while 0 <= nr < 4 and 0 <= nc < 4 and board[nr][nc] == 'x':
                count += 1
                nr -= dr
                nc -= dc
            if count >= 3:
                return True
        return False

    # Try every empty cell
    for i in range(4):
        for j in range(4):
            if board[i][j] == '.':
                if check_win_after_move(i, j):
                    print("YES")
                    return

    print("NO")

if __name__ == "__main__":
    solve()

def get_winning_lines():
