    # Rows
    for r in range(4):
        for c in range(2):
            lines.append([(r, c), (r, c+1), (r, c+2)])
    # Columns
    for c in range(4):
        for r in range(2):
            lines.append([(r, c), (r+1, c), (r+2, c)])
    # Diagonals down-right
    for r in range(2):
        for c in range(2):
            lines.append([(r, c), (r+1, c+1), (r+2, c+2)])
    # Diagonals down-left
    for r in range(2):
        for c in range(2, 4):
            lines.append([(r, c), (r+1, c-1), (r+2, c-2)])
    return lines

